using System;using Microsoft.Extensions.Hosting;namespace DoctorLoan.WebAPI.Middlewares;public static class CustomMiddlewareExtensions{    public static void UseRequestResponseLogging(this IApplicationBuilder app) => app.UseMiddleware<RequestResponseLoggerMiddleware>();    //public static void UseNetworkAvaliable(this IApplicationBuilder app) => app.UseMiddleware<NetworkMiddleware>();    public static void UseStandardSecurityHeaders(this IApplicationBuilder app)    {        app.Use(async (context, next) =>        {            var headers = context.Response.Headers;            headers["X-Content-Type-Options"] = "nosniff";            headers["X-Frame-Options"] = "DENY";            headers["Referrer-Policy"] = "no-referrer";            headers["X-XSS-Protection"] = "0";            if (!headers.ContainsKey("Content-Security-Policy"))            {                var env = context.RequestServices.GetService(typeof(IHostEnvironment)) as IHostEnvironment;                var isDevelopment = env?.IsDevelopment() ?? false;                var isSwaggerUi = context.Request.Path.StartsWithSegments("/api", StringComparison.OrdinalIgnoreCase);                var devConnectExtras = isDevelopment ? " http://localhost:* https://localhost:* ws://localhost:* wss://localhost:*" : string.Empty;                headers["Content-Security-Policy"] = isSwaggerUi                    ? $"default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; font-src 'self'; connect-src 'self'{devConnectExtras}; frame-ancestors 'none'; base-uri 'none'"                    : $"default-src 'none'; connect-src 'self'{devConnectExtras}; frame-ancestors 'none'; base-uri 'none'";            }            await next();        });    }}
